// Automatisch erzeugt von tools/kurs-builder/build.py – nicht von Hand ändern. Inhalte: tools/kurs-builder/inhalte.py
(function(){var A={"ki-basics": {"status": "live", "code": "FLOW-BASICS-41", "dauer": "ca. 14 Min. Video · ca. 4 Std. Umsetzen", "hinweis": "Animierte Videos mit KI-Stimme (gekennzeichnet). Jede Lektion endet mit einer Aufgabe.", "intro": {"video": "kurse/ki-basics/videos/L00.mp4", "poster": "kurse/ki-basics/videos/L00.jpg", "titel": "KI ist dein Mitarbeiter – so führst du ihn"}, "module": ["KI als Mitarbeiter behandeln", "Context is King", "Weniger prompten, mehr sprechen", "Briefing, Delegieren, Feedback", "Wie funktioniert KI?", "Die verschiedenen KI-Modelle", "Prompting & Kommunikation", "Claude Code oder Codex einrichten", "Projekte einrichten", "CLAUDE.md – dauerhafter Kontext", "Rules – Regeln und Vorgaben", "Dateien, Wissen und Dokumente", "Skills – eigene KI-Fähigkeiten", "MCPs & Konnektoren", "Agenten und Subagents", "Tools & Tool Use", "Tokens, Context Window, Kosten", "Multimodale KI", "Halluzinationen und Qualitätskontrolle", "Datenschutz und Sicherheit"], "bereiche": {"0": "AI Mindset · Die richtige Zusammenarbeit", "4": "AI Fundamentals · Die Technik verstehen", "7": "AI Workspace · Deine Arbeitsumgebung", "12": "AI Extensions · Fähigkeiten erweitern", "14": "AI Agents · KI eigenständig arbeiten lassen", "16": "AI Productivity & Safety · Effizient und sicher"}, "lektionen": [{"videos": [["kurse/ki-basics/videos/L01.mp4", "kurse/ki-basics/videos/L01.jpg", "KI als Mitarbeiter behandeln"]], "text": "Wer KI wie einen neuen Mitarbeiter einarbeitet, bekommt andere Ergebnisse als jemand, der nur Fragen stellt. Rolle, Kontext, Aufgabe, Feedback – und du behältst die Kontrolle.", "punkte": ["<b>Rolle</b>: Sag der KI, als was sie für dich arbeitet (Texterin, Berater, Entwickler)", "<b>Kontext</b>: dein Unternehmen, deine Ziele, deine Arbeitsweise", "<b>Aufgabe</b>: das gewünschte Ergebnis, nicht jeder einzelne Klick", "<b>Feedback</b>: korrigieren statt neu anfangen", "<b>Kontrolle</b>: wichtige Ergebnisse prüfst du, Grenzen legst du fest"], "aufgabe": "Gib deiner KI eine Rolle und lass sie dir die Fragen eines neuen Mitarbeiters stellen.", "prompt": "Du arbeitest ab jetzt als [Rolle] für mich. Bevor du loslegst: Stell mir die Fragen, die ein neuer Mitarbeiter am ersten Tag stellen würde, damit du mich, mein Angebot und meine Ziele verstehst.", "bereich": "AI Mindset · Die richtige Zusammenarbeit"}, {"videos": [["kurse/ki-basics/videos/L02.mp4", "kurse/ki-basics/videos/L02.jpg", "Context is King"]], "text": "KI ohne Kontext liefert Durchschnitt. Je besser sie dich, deine Zielgruppe und deine Beispiele kennt, desto weniger musst du nacharbeiten.", "punkte": ["Ohne Kontext rät die KI – das Ergebnis passt „für alle“", "<b>Wer du bist</b>: Angebot, Werte, Tonfall", "<b>Für wen</b>: Zielgruppe und ihr Problem", "<b>Beispiele</b>: ein Text, der dir gefällt, sagt mehr als zehn Adjektive", "Dauerhaft ablegen: siehe Lektion 09 (Projekte) und 10 (CLAUDE.md)"], "aufgabe": "Lass dir ein „Über mich“-Dokument schreiben und speichere es ab.", "prompt": "Ich gebe dir jetzt Kontext zu mir. Fass ihn danach in einem „Über mich“-Dokument zusammen, das ich in jedem neuen Chat verwenden kann: Wer ich bin, was ich anbiete, für wen, mein Ton, was ich nicht will. Hier meine Infos: [frei erzählen oder einfügen]"}, {"videos": [["kurse/ki-basics/videos/L03.mp4", "kurse/ki-basics/videos/L03.jpg", "Weniger prompten, mehr sprechen"]], "text": "Voice Prompting heißt: frei einsprechen statt Prompts bauen. Du lieferst mehr Kontext in weniger Zeit, und die KI macht aus ungefilterten Gedanken eine Struktur.", "punkte": ["Mikrofon-Symbol in der KI-App oder Diktierfunktion deines Handys nutzen", "Erst sagen, was die KI mit dem Gesagten tun soll", "Unsortiert reden ist erlaubt – ordnen ist ihre Aufgabe", "Im Dialog bleiben: Rückfragen beantworten statt neu anfangen", "Schreiben, wenn es exakt sein muss (Namen, Zahlen, Regeln)"], "aufgabe": "Sprich eine Idee ein bis zwei Minuten frei ein und lass sie von der KI ordnen.", "prompt": "Ich erzähle dir gleich frei von meiner Idee. Hör erst zu. Dann ordne meine Gedanken in: Ziel, wichtigste Punkte, offene Fragen, nächste drei Schritte. Stell mir Rückfragen, wenn etwas unklar ist."}, {"videos": [["kurse/ki-basics/videos/L04.mp4", "kurse/ki-basics/videos/L04.jpg", "Briefing, Delegieren, Feedback"]], "text": "Gute Zusammenarbeit mit KI sieht aus wie gute Führung: klares Briefing, Verantwortung für das Ergebnis abgeben, ehrliches Feedback – und Grenzen, die du festlegst.", "punkte": ["<b>Briefing</b>: Ziel, Kontext, Rahmen, „fertig heißt …“", "<b>Delegieren</b>: Ergebnis beschreiben, die KI einen Weg vorschlagen lassen", "<b>Feedback</b>: konkret sagen, was gut ist und was anders soll – nicht neu anfangen", "<b>Grenzen</b>: was sie nicht tun soll (z. B. nichts erfinden, nichts versenden)", "Bewährtes Feedback wird später zur festen Regel (Lektion 11)"], "aufgabe": "Delegiere heute eine echte Aufgabe mit diesem Briefing und gib zweimal Feedback.", "prompt": "Ich brauche [Ergebnis]. Ziel: [wozu]. Für: [Zielgruppe]. Rahmen: [Länge, Format, Ton]. Fertig ist es, wenn [Kriterium]. Schlag mir erst kurz deinen Weg vor, dann leg los. Erfinde nichts – frag nach, wenn dir etwas fehlt."}, {"videos": [["kurse/ki-basics/videos/L05.mp4", "kurse/ki-basics/videos/L05.jpg", "Wie funktioniert KI?"]], "text": "Du musst die Technik nicht im Detail kennen. Ein Bild reicht: Ein Sprachmodell sagt das wahrscheinlichste nächste Wort voraus. Das erklärt seine Stärken – und warum es manchmal Dinge erfindet.", "punkte": ["<b>KI</b>: Oberbegriff für Systeme, die Aufgaben lösen, für die man sonst Denken braucht", "<b>LLM</b> (Large Language Model): Sprachmodell, trainiert mit sehr viel Text", "Antwort entsteht Wort für Wort nach Wahrscheinlichkeit", "<b>Halluzination</b>: eine erfundene, aber plausibel klingende Aussage", "Mehr dazu: Lektion 19 (Qualitätskontrolle)"], "aufgabe": "Frag deine KI nach etwas, das du sicher weißt, und prüf die Antwort auf Fehler.", "bereich": "AI Fundamentals · Die Technik verstehen"}, {"videos": [["kurse/ki-basics/videos/L06.mp4", "kurse/ki-basics/videos/L06.jpg", "Die verschiedenen KI-Modelle"]], "text": "Du brauchst nicht jedes neue Tool. Ein Assistent, den du gut kennst und der dich kennt, bringt mehr als fünf, die du nur ausprobiert hast. Die Modelle ändern sich schnell – das Prinzip bleibt.", "punkte": ["<b>Claude</b>: Maiks Hauptwerkzeug für Texte, Websites, Apps und Automatisierungen", "<b>ChatGPT</b>: breiter Alltags-Assistent, stark bei Bildern", "<b>Gemini</b>: praktisch, wenn du tief in Google-Diensten steckst", "Schnelles Modell für Alltägliches, starkes Modell für Wichtiges", "Entscheidend ist, dass die KI dich und deine Ziele kennt – nicht der Markenname"], "aufgabe": "Entscheide dich für einen Assistenten und finde heraus, wo du dort das Modell wechselst.", "links": [["Claude", "https://claude.ai", "Assistent von Anthropic"], ["ChatGPT", "https://chatgpt.com", "Assistent von OpenAI"], ["Gemini", "https://gemini.google.com", "Assistent von Google"]]}, {"videos": [["kurse/ki-basics/videos/L07.mp4", "kurse/ki-basics/videos/L07.jpg", "Prompting & Kommunikation"]], "text": "Die meisten schlechten Antworten liegen am Auftrag, nicht an der KI. Vier Angaben und ein Beispiel reichen – danach schärfst du im Gespräch nach.", "punkte": ["<b>Rolle</b>: wer du bist und worum es geht", "<b>Ergebnis</b>: Format, Länge", "<b>Für wen</b>: Zielgruppe und Ton", "<b>Tabu</b>: was nicht vorkommen soll", "<b>Beispiel</b>: zeig, was dir gefällt", "Danach nachschärfen statt neu anfangen"], "aufgabe": "Kopier den Prompt, füll die Klammern für eine echte Aufgabe aus und schärfe das Ergebnis zweimal nach.", "prompt": "Ich bin [Beruf/Rolle]. Schreib mir [Ergebnis] für [Zielgruppe], [Länge], im Ton [locker/sachlich]. Vermeide [Tabu]. Hier ein Beispiel, das mir gefällt: [Beispiel]. Gib mir drei Varianten."}, {"videos": [["kurse/ki-basics/videos/L08.mp4", "kurse/ki-basics/videos/L08.jpg", "Claude Code oder Codex einrichten"]], "text": "Claude Code und Codex sind Agenten: Sie arbeiten auf deinem Computer, in einem Ordner, den du auswählst. Darum nimmst du die Desktop-App statt des Browser-Chats. Du brauchst nur eine der beiden: Hast du ein bezahltes Claude-Abo, nimm Claude Code. Zahlst du für ChatGPT, nimm Codex. Dauer: etwa 15 Minuten.", "punkte": ["<b>Claude Code</b>: claude.com/download → anmelden → oben auf <b>Code</b> → Ordner wählen", "<b>Codex</b>: ChatGPT-Desktop-App → <b>Codex</b> → New chat → Ordner öffnen", "<b>Modell</b>: Opus 5.5 auf Medium als Standard", "<b>Modus</b>: Auto (sonst Accept edits) – nie Bypass permissions"], "aufgabe": "Installiere Claude Code oder Codex, wähl einen Ordner „workshop“ und lass eine Datei hallo.html anlegen.", "prompt": "Leg in diesem Ordner eine Datei hallo.html an: eine kleine Seite mit meinem Namen und dem heutigen Datum.", "links": [["Claude herunterladen", "https://claude.com/download", "Desktop-App von Anthropic"], ["ChatGPT herunterladen", "https://chatgpt.com/download/", "Desktop-App mit Codex"]], "bereich": "AI Workspace · Deine Arbeitsumgebung", "frei": true, "abschnitte": [["Chat ist nicht gleich Agent", "<p>Claude und ChatGPT gibt es in drei Formen: <b>Web</b> (im Browser, sieht nichts auf deinem Computer), <b>Desktop-App</b> (der Agent arbeitet direkt mit deinen Dateien) und <b>Terminal</b> (dasselbe als Befehl, für Fortgeschrittene). Ein Chat beantwortet Fragen. Ein Agent bekommt eine Aufgabe und erledigt sie: Er legt Dateien an und baut Websites und Apps.</p>"], ["Variante A · Claude Code", "<p>Voraussetzung: ein bezahltes Claude-Abo (Pro oder höher).</p><ol><li><b>Herunterladen:</b> <a href=\"https://claude.com/download\" target=\"_blank\" rel=\"noopener\">claude.com/download</a> erkennt Mac oder Windows. Mac: Claude in „Programme“ ziehen. Windows: Installer starten.</li><li><b>Anmelden</b> mit deinem Claude-Konto. Du landest zuerst im Chat.</li><li><b>Oben auf „Code“ klicken.</b> Erst dort arbeitet Claude als Agent auf deinem Computer.</li><li><b>Ordner wählen:</b> Leg auf dem Schreibtisch einen leeren Ordner <code>workshop</code> an und wähl ihn unter dem Eingabefeld aus. Claude arbeitet nur darin.</li></ol><figure><img src=\"kurse/ki-basics/bilder/claude-code-desktop.jpg\" alt=\"Claude Code in der Desktop-App: Aufgabe eingeben, Claude liest und schreibt Dateien. Unten links der Modus.\" loading=\"lazy\"><figcaption>Claude Code in der Desktop-App: Aufgabe eingeben, Claude liest und schreibt Dateien. Unten links der Modus. <span>Bild: Anthropic</span></figcaption></figure><figure><img src=\"kurse/ki-basics/bilder/claude-code-ordner.jpg\" alt=\"Bereit zum Loslegen: oben das Eingabefeld, darunter wählst du, woran Claude arbeitet.\" loading=\"lazy\"><figcaption>Bereit zum Loslegen: Eingabefeld und darunter der Projektordner. <span>Bild: Anthropic</span></figcaption></figure><p>Windows: Meldet die App „Git is required“, installiere <b>Git for Windows</b> (einfach durchklicken) und starte Claude neu.</p>"], ["Variante B · Codex", "<p>Voraussetzung: ein ChatGPT-Konto, sicher mit bezahltem Plus-Abo.</p><ol><li><b>Herunterladen:</b> Codex steckt in der ChatGPT-Desktop-App: <a href=\"https://chatgpt.com/download/\" target=\"_blank\" rel=\"noopener\">chatgpt.com/download</a>.</li><li><b>Anmelden</b> mit deinem ChatGPT-Konto.</li><li><b>Auf „Codex“ wechseln</b> und mit <b>New chat</b> starten. Der Schalter Chat/Work über dem Eingabefeld gehört zu ChatGPT, nicht zu Codex.</li><li><b>Ordner öffnen:</b> leeren Ordner <code>workshop</code> anlegen und in Codex öffnen.</li></ol><figure><img src=\"kurse/ki-basics/bilder/codex-app.jpg\" alt=\"Die Codex-App: links „New chat“ und deine Projekte, unten das Eingabefeld.\" loading=\"lazy\"><figcaption>Die Codex-App: links „New chat“ und deine Projekte, unten das Eingabefeld. <span>Bild: OpenAI</span></figcaption></figure><figure><img src=\"kurse/ki-basics/bilder/codex-seitenleiste.jpg\" alt=\"Oben „Codex“ wählen, dann „New chat“.\" loading=\"lazy\"><figcaption>Oben „Codex“ wählen, dann „New chat“. <span>Bild: OpenAI</span></figcaption></figure>"], ["Modell und Berechtigung", "<p><b>Modell</b> (Stand November 2026): <b>Opus 5.5 auf Medium</b> für fast alles, <b>Haiku 5.5</b> für schnelle kleine Aufgaben, <b>Fable 5.2</b> für sehr große Projekte. In Codex nimmst du das empfohlene Standardmodell.</p><p><b>Berechtigung</b> (Leiste unter dem Eingabefeld): <b>Auto</b> – arbeitet flüssig und fragt nur bei Riskantem. Gibt es Auto nicht, nimm <b>Accept edits</b>. <b>Manual</b> fragt bei jedem Schritt, <b>Plan</b> plant nur. <b>Bypass permissions nie verwenden.</b> In Codex lässt du die Voreinstellung, wie sie ist.</p>"], ["Der Test", "<p>Schreib mit ausgewähltem Ordner <code>workshop</code> den Prompt unten in Claude Code oder Codex. Liegt danach <code>hallo.html</code> in deinem Ordner, bist du startklar.</p><ul><li>☐ Desktop-App installiert</li><li>☐ angemeldet, bezahltes Abo aktiv</li><li>☐ „Code“ bzw. „Codex“ geöffnet</li><li>☐ Ordner <code>workshop</code> ausgewählt</li><li>☐ Testdatei angelegt</li></ul><p>Hängst du irgendwo? Schreib mit Screenshot in die Tech-Support-Gruppe.</p>"], ["Optional · Terminal für Fortgeschrittene", "<p>Für den Workshop reicht die Desktop-App. Befehle aus den offiziellen Anleitungen:</p><p><b>Claude Code</b> – Mac/Linux: <code>curl -fsSL https://claude.ai/install.sh | bash</code><br>Windows (PowerShell): <code>irm https://claude.ai/install.ps1 | iex</code><br>Danach im Projektordner <code>claude</code> eingeben.</p><p><b>Codex</b> – Mac/Linux: <code>curl -fsSL https://chatgpt.com/codex/install.sh | sh</code><br>Windows: <code>powershell -ExecutionPolicy ByPass -c \"irm https://chatgpt.com/codex/install.ps1 | iex\"</code><br>Danach <code>codex</code> eingeben und „Sign in with ChatGPT“ wählen.</p><figure><img src=\"kurse/ki-basics/bilder/claude-code-terminal.jpg\" alt=\"Claude Code im Terminal.\" loading=\"lazy\"><figcaption>Claude Code im Terminal. <span>Bild: Anthropic</span></figcaption></figure>"]]}, {"videos": [["kurse/ki-basics/videos/L09.mp4", "kurse/ki-basics/videos/L09.jpg", "Projekte einrichten"]], "text": "Projekte machen aus einzelnen Chats eine Arbeitsumgebung. Die KI kennt dort deine Anweisungen und Unterlagen dauerhaft – du erklärst nichts mehr doppelt.", "punkte": ["In Claude: links „Projekte“ → neues Projekt anlegen", "Projektanweisung: wer du bist, worum es hier geht, wie Ergebnisse aussehen sollen", "Unterlagen ins Projektwissen legen (siehe Lektion 12)", "Ein Projekt pro Aufgabenbereich statt eines für alles", "Das Prinzip gibt es auch bei anderen Assistenten"], "aufgabe": "Leg ein Projekt für deinen wichtigsten Arbeitsbereich an und füg dein „Über mich“-Dokument ein.", "links": [["Claude Projekte", "https://claude.ai/projects", "Hier legst du Projekte an"]]}, {"videos": [["kurse/ki-basics/videos/L10.mp4", "kurse/ki-basics/videos/L10.jpg", "CLAUDE.md – dauerhafter Kontext"]], "text": "Die CLAUDE.md ist dein dauerhafter Kontext als Datei: Wer du bist, wie du arbeitest, was gilt. Claude Code liest sie automatisch. Derselbe Inhalt funktioniert als Projektanweisung in der App.", "punkte": ["Liegt im Hauptordner deines Projekts und wird von Claude Code automatisch gelesen", "Inhalt: wer du bist, Zielgruppe, Ton, Regeln, wichtige Ordner", "Kurz halten – lieber eine klare Seite als zehn vage", "Wiederkehrende Korrekturen dort eintragen", "Vertiefung im Kurs 05 „Claude Code“"], "aufgabe": "Lass dir deine erste CLAUDE.md schreiben – oder füg den Text als Projektanweisung ein.", "prompt": "Lies mein „Über mich“-Dokument und schreib daraus eine CLAUDE.md: Wer ich bin, für wen ich arbeite, mein Ton, meine Regeln. Halte sie auf einer Seite. Frag nach, was dir noch fehlt."}, {"videos": [["kurse/ki-basics/videos/L11.mp4", "kurse/ki-basics/videos/L11.jpg", "Rules – Regeln und Vorgaben"]], "text": "Regeln sind dein Standard: Ton, Qualität, Tabus. Abgelegt in der Projektanweisung oder CLAUDE.md gelten sie dauerhaft – so arbeitet die KI jedes Mal nach deinen Vorgaben.", "punkte": ["Regeln kurz und eindeutig formulieren („immer“, „nie“, „nur wenn“)", "Ablegen: Projektanweisung in der App, CLAUDE.md oder der Ordner <code>.claude/rules</code> in Claude Code", "Mit Begründung funktionieren Regeln besser („weil …“)", "Zweimal korrigiert? Dann wird es eine Regel", "Wenige klare Regeln schlagen eine lange Liste"], "aufgabe": "Schreib fünf Regeln auf, die deine KI immer einhalten soll, und leg sie dauerhaft ab.", "prompt": "Schau dir unser Gespräch an: Welche Korrekturen habe ich dir gegeben? Formuliere daraus kurze, eindeutige Regeln, die ich in meine Projektanweisung oder CLAUDE.md übernehmen kann."}, {"videos": [["kurse/ki-basics/videos/L12.mp4", "kurse/ki-basics/videos/L12.jpg", "Dateien, Wissen und Dokumente"]], "text": "Mit eigenen Dateien wird aus allgemeinem Wissen dein Wissen. Leg ab, was du oft brauchst – und halte es aktuell, denn die KI kennt nur den Stand der Datei.", "punkte": ["Dateien direkt in den Chat ziehen oder ins Projektwissen legen", "Gut geeignet: Zusammenfassen, Fragen, Vergleichen, Weiterverarbeiten", "Wichtige Zahlen aus Dokumenten selbst gegenprüfen", "Unterlagen aktuell halten – alte Preisliste, alte Antworten", "Vorher prüfen, ob die Datei sensible Daten enthält (Lektion 20)"], "aufgabe": "Lad ein eigenes Dokument hoch und lass es mit dem Prompt auswerten.", "prompt": "Lies das angehängte Dokument. Gib mir: 1. die fünf wichtigsten Punkte, 2. was für mich als [Rolle] daraus folgt, 3. was unklar ist oder fehlt. Zitiere die Stellen, auf die du dich beziehst."}, {"videos": [["kurse/ki-basics/videos/L13.mp4", "kurse/ki-basics/videos/L13.jpg", "Skills – eigene KI-Fähigkeiten"]], "text": "Skills machen wiederkehrende Abläufe reproduzierbar: Was einmal gut funktioniert hat, wird zur Anleitung, die die KI immer wieder nutzt.", "punkte": ["Ein Skill = Ordner mit <code>SKILL.md</code> plus Vorlagen und Beispielen", "Die Beschreibung entscheidet, wann die KI ihn lädt", "Fertige Skills installieren oder eigene aus einer gelungenen Session bauen", "Funktioniert in Claude Code, der Claude-App und Codex", "Vertiefung im Kurs 08 „Skills bauen &amp; verkaufen“"], "aufgabe": "Installiere einen Free-Skill aus dem Store und lass die KI damit eine Aufgabe erledigen.", "links": [["Installation", "skills/INSTALLATION.md", "So legst du einen Skill ab"], ["Flow DNA Store", "?tab=home", "Fertige Skills zum Ausprobieren"]], "bereich": "AI Extensions · Fähigkeiten erweitern"}, {"videos": [["kurse/ki-basics/videos/L14.mp4", "kurse/ki-basics/videos/L14.jpg", "MCPs & Konnektoren"]], "text": "MCP (Model Context Protocol) ist ein offener Standard, über den KI auf externe Programme zugreift. Konnektoren sind fertige Verbindungen auf dieser Basis – du richtest sie in den Einstellungen ein und entscheidest, was erlaubt ist.", "punkte": ["<b>MCP</b>: der Standard (die „Steckdose“)", "<b>MCP-Server</b>: stellt Daten und Aktionen eines Programms bereit", "<b>Konnektor</b>: fertige Verbindung in der App, meist per Anmeldung eingerichtet", "In Claude: Einstellungen → Konnektoren", "Regel: so wenig Zugriff wie möglich, Schreibrechte nur mit Rückfrage"], "aufgabe": "Verbinde einen Dienst (z. B. Google Drive) und lass die KI dort eine Datei finden und zusammenfassen."}, {"videos": [["kurse/ki-basics/videos/L15.mp4", "kurse/ki-basics/videos/L15.jpg", "Agenten und Subagents"]], "text": "Ein Agent ist KI, die ein Ziel selbstständig in Schritten verfolgt und dabei Werkzeuge nutzt. Subagents teilen große Aufgaben auf. Je mehr sie selbst tun, desto wichtiger sind dein Briefing und deine Grenzen.", "punkte": ["<b>Chatbot</b>: antwortet – <b>Agent</b>: plant, handelt, prüft", "<b>Subagent</b>: Helfer für eine Teilaufgabe mit eigenem, frischem Kontext", "Sinnvoll bei vielen Schritten, Recherche oder paralleler Arbeit", "Gutes Briefing (Lektion 04) wird hier noch wichtiger", "Praxis im Kurs 05 „Claude Code“ und Kurs 07 „Automatisierung“"], "aufgabe": "Notier eine Aufgabe aus deinem Alltag mit mindestens fünf Schritten, die ein Agent übernehmen könnte.", "bereich": "AI Agents · KI eigenständig arbeiten lassen"}, {"videos": [["kurse/ki-basics/videos/L16.mp4", "kurse/ki-basics/videos/L16.jpg", "Tools & Tool Use"]], "text": "Mit Tools wird aus einem Gesprächspartner ein Umsetzer: recherchieren, Dateien bauen, Daten auswerten, in Programmen handeln. Welche Tools erlaubt sind, legst du fest.", "punkte": ["Websuche: für Aktuelles – Quellen anzeigen lassen", "Dateien: Dokumente, Tabellen, Präsentationen, Code", "Datenanalyse: Tabelle hochladen, Fragen stellen", "Aktionen über Konnektoren (Lektion 14)", "Kritisches (Senden, Löschen, Bezahlen) nur mit deiner Freigabe"], "aufgabe": "Lass deine KI etwas Aktuelles mit Websuche recherchieren und prüf zwei der Quellen.", "prompt": "Recherchiere im Web: [Thema]. Gib mir die fünf wichtigsten Punkte mit Quelle und Datum. Sag ehrlich, wo die Quellen dünn sind oder sich widersprechen."}, {"videos": [["kurse/ki-basics/videos/L17.mp4", "kurse/ki-basics/videos/L17.jpg", "Tokens, Context Window, Kosten"]], "text": "Tokens sind die Währung der KI, das Context Window ihr Arbeitsgedächtnis. Wer beides versteht, bekommt bessere Antworten und stößt seltener an Limits.", "punkte": ["<b>Token</b>: Wortstück – Eingabe und Ausgabe werden in Tokens gezählt", "<b>Context Window</b>: alles, was die KI gerade „im Kopf“ hat", "Im Abo: Nutzungslimits – über die Schnittstelle (API): Abrechnung nach Tokens", "Lange Chats werden ungenauer: zusammenfassen lassen und neu starten", "Dauerhaftes gehört in Projekt, CLAUDE.md oder Skill"], "aufgabe": "Lass dir einen langen Chat zusammenfassen und mach in einem neuen Chat weiter.", "prompt": "Fass unseren bisherigen Chat so zusammen, dass ich in einem neuen Chat nahtlos weitermachen kann: Ziel, Entscheidungen, aktueller Stand, offene Punkte.", "bereich": "AI Productivity & Safety · Effizient und sicher"}, {"videos": [["kurse/ki-basics/videos/L18.mp4", "kurse/ki-basics/videos/L18.jpg", "Multimodale KI"]], "text": "Multimodal heißt: Die KI arbeitet mit Text, Bild, Ton und Video. Im Alltag bringt dir vor allem das Lesen von Bildern und Screenshots sofort etwas.", "punkte": ["Screenshot statt Beschreibung: Fehler, Formulare, Designs", "Fotos von Notizen und Whiteboards abtippen lassen", "Bild-, Stimm- und Videoerzeugung: oft eigene Tools", "KI-Bilder und KI-Stimmen kennzeichnen, wenn sie echt wirken könnten", "Keine echten Personen ohne deren Einverständnis nachbilden"], "aufgabe": "Mach einen Screenshot von etwas, das du nicht verstehst, und lass es dir erklären."}, {"videos": [["kurse/ki-basics/videos/L19.mp4", "kurse/ki-basics/videos/L19.jpg", "Halluzinationen und Qualitätskontrolle"]], "text": "Halluzinationen lassen sich nicht ganz abstellen, aber gut abfangen: Quellen verlangen, Stichproben prüfen, nach Unsicherheit fragen. Die Verantwortung für das Ergebnis bleibt bei dir.", "punkte": ["Warum es passiert: siehe Lektion 05", "Regel hinterlegen: „Nichts erfinden – sag, wenn du etwas nicht weißt“", "Bei Fakten: Websuche einschalten und Quellen prüfen", "Zweiter Blick: Ergebnis in neuem Chat kritisch prüfen lassen", "Rechtliches, Medizinisches, Finanzielles: Fachleute fragen"], "aufgabe": "Lass ein KI-Ergebnis mit dem Prompt prüfen und kontrolliere zwei Fakten selbst.", "prompt": "Prüf deinen letzten Text kritisch: Welche Aussagen sind Fakten, die ich gegenprüfen sollte? Wobei bist du unsicher? Was hast du angenommen, ohne es zu wissen? Liste das ehrlich auf."}, {"videos": [["kurse/ki-basics/videos/L20.mp4", "kurse/ki-basics/videos/L20.jpg", "Datenschutz und Sicherheit"]], "text": "Wer die Grenzen kennt, arbeitet entspannt mit KI: keine sensiblen Daten eingeben, Zugriffe klein halten, kritische Aktionen selbst freigeben. Das ist keine Rechtsberatung – bei Kundendaten im Zweifel fachlich klären.", "punkte": ["Keine Passwörter, Zugangsdaten oder echten Kundendaten in den Chat", "Namen und Details durch Platzhalter ersetzen", "In den Einstellungen prüfen, ob deine Chats zum Training genutzt werden", "Regeln deines Arbeitgebers zur KI-Nutzung beachten", "Konnektoren: wenig Rechte, Rückfrage vor Senden/Löschen, regelmäßig aufräumen", "Bei personenbezogenen Daten im Geschäft: Datenschutz fachlich klären"], "aufgabe": "Öffne die Datenschutz-Einstellungen deiner KI und schreib drei Dinge auf, die du nie eingibst."}], "spick": [["Mitarbeiter-Formel", "Rolle geben\nKontext erklären\nErgebnis übertragen\nFeedback geben\nKontrolle behalten"], ["Briefing", "Ziel: Was soll da sein?\nKontext: Für wen, wozu?\nRahmen: Länge, Ton, Tabus\nFertig heißt: …"], ["Dauerhafter Kontext", "Projekt → Anweisung + Wissen\nCLAUDE.md → Handbuch\nRules → gilt immer\nSkill → Ablauf"], ["Prüf-Routine", "Quelle zeigen lassen\nStichprobe prüfen\n„Was ist unsicher?“\nSelbst entscheiden"], ["Nie eingeben", "Passwörter\nKundendaten mit Namen\nVertrauliches aus dem Job"]], "faq": [["Die Antworten sind zu allgemein.", "Dann fehlt Kontext: wer du bist, für wen das Ergebnis ist und ein Beispiel, das dir gefällt (Lektion 02). Danach nachschärfen."], ["Muss ich alle 20 Lektionen der Reihe nach machen?", "Der Bereich „AI Mindset“ (Lektion 01–04) ist die Grundlage. Danach kannst du springen – die Lektionen verweisen aufeinander."], ["Stimmt das, was die KI sagt?", "Nicht immer. Fakten, Zahlen und Quellen prüfst du selbst – besonders bei Recht, Gesundheit und Geld (Lektion 19)."], ["Brauche ich ein bezahltes Abo?", "Zum Lernen reicht meist die kostenlose Version. Ein Abo lohnt sich, wenn du täglich damit arbeitest. Projekte, Konnektoren und starke Modelle sind je nach Anbieter Teil des Abos."], ["Ich nutze nicht Claude. Geht der Kurs trotzdem?", "Ja. Claude ist das Beispiel, die Prinzipien (Kontext, Briefing, Regeln, Prüfen) gelten für jeden Assistenten. CLAUDE.md und Skills sind am stärksten in Claude."], ["Ich hänge fest.", "Frag in der Tech-Support-Gruppe (Tab Community) – dort helfen Maik und die Community."]], "ende": {"titel": "Du führst jetzt deine KI.", "text": "Du weißt, wie du Kontext gibst, delegierst, deine Arbeitsumgebung aufbaust und Ergebnisse prüfst. Nächster Schritt: Halte fest, wer du bist – im Kurs „Mit KI zur Personal Brand“ wird daraus ein Skill, den jede KI nutzt."}}, "personal-brand": {"status": "live", "code": "FLOW-BRAND-58", "dauer": "ca. 3 Min. Video · 90 Min. Umsetzen", "hinweis": "Animierte Videos mit KI-Stimme (gekennzeichnet). Jede Lektion endet mit einer Aufgabe.", "intro": {"video": "kurse/personal-brand/videos/L00.mp4", "poster": "kurse/personal-brand/videos/L00.jpg", "titel": "Deine Marke als Skill"}, "module": ["Brand DNA: Wer bist du?", "Deine Stimme als Skill", "Look ohne Designer", "Fotos richtig nutzen", "Dein Brand-Paket"], "bereiche": {}, "lektionen": [{"videos": [["kurse/personal-brand/videos/L01.mp4", "kurse/personal-brand/videos/L01.jpg", "Brand DNA: Wer bist du?"]], "text": "Bevor die KI für dich schreibt, muss sie dich kennen. Deine Brand DNA ist eine Seite Text: wer du bist, für wen du arbeitest, warum du es tust.", "punkte": ["<b>Wer</b>: Angebot, Stärken, deine Geschichte", "<b>Für wen</b>: Zielgruppe und ihr Problem in ihren Worten", "<b>Warum</b>: Werte und Antrieb", "Nur Echtes: keine erfundenen Kunden, Zahlen oder Erfolge"], "aufgabe": "Lass dich von der KI interviewen und speichere das Ergebnis als Datei „brand-dna“.", "prompt": "Interviewe mich zu meiner Marke. Stell mir nacheinander 10 Fragen zu mir, meiner Zielgruppe und meinem Warum. Warte nach jeder Frage auf meine Antwort. Fass danach alles auf einer Seite als „Brand DNA“ zusammen."}, {"videos": [["kurse/personal-brand/videos/L02.mp4", "kurse/personal-brand/videos/L02.jpg", "Deine Stimme als Skill"]], "text": "Deine Stimme ist das, woran man deine Texte erkennt. Als Skill gespeichert, musst du sie nie wieder erklären.", "punkte": ["Drei echte Texte als Vorlage – keine geschönten", "Regeln kurz und konkret: „du, kurze Sätze, keine Floskeln“", "Auch aufschreiben, was du <b>nicht</b> willst", "Als <code>SKILL.md</code> im Ordner <code>skills/dein-name-brand</code> speichern"], "aufgabe": "Gib der KI drei Texte von dir und lass daraus deine SKILL.md schreiben.", "prompt": "Hier sind drei Texte von mir: [einfügen]. Beschreib meine Stimme: Anrede, Satzlänge, Ton, typische Wörter, was ich vermeide. Schreib daraus eine SKILL.md mit name, description und klaren Regeln."}, {"videos": [["kurse/personal-brand/videos/L03.mp4", "kurse/personal-brand/videos/L03.jpg", "Look ohne Designer"]], "text": "Du brauchst keinen Designer für den Anfang. Drei klare Entscheidungen – Farben, Schrift, Bildstil – und alles wirkt wie aus einem Guss.", "punkte": ["Zwei Grundfarben plus <b>ein</b> Akzent", "Ein Schriftpaar: markante Überschrift, gut lesbarer Text", "Ein Bildstil, der zu dir passt – und dabei bleiben", "Regeln mit Hex-Codes in den Skill schreiben"], "aufgabe": "Lass dir drei Looks vorschlagen und entscheide dich für einen.", "prompt": "Schau dir mein Logo und diese Fotos an: [anhängen]. Schlag mir 3 Looks vor: Farben mit Hex-Code, Schriftpaar (Google Fonts), Bildstil. Zeig jeden Look als kleine Beispielseite. Schreib den gewählten Look als Regeln in meinen Brand-Skill."}, {"videos": [["kurse/personal-brand/videos/L04.mp4", "kurse/personal-brand/videos/L04.jpg", "Fotos richtig nutzen"]], "text": "Deine Fotos sind dein stärkstes Material. Fünf gute, echte Bilder im selben Stil reichen für Website, Posts und Profil.", "punkte": ["Fünf Motive: Porträt, Arbeit, Ergebnis, persönlich, Querformat", "Tageslicht am Fenster, ruhiger Hintergrund, Handy reicht", "Einheitlicher Stil – z. B. alles schwarz-weiß", "KI zum Verbessern nutzen, nicht zum Erfinden"], "aufgabe": "Leg einen Ordner „Fotos“ an und sammle deine fünf besten Bilder."}, {"videos": [["kurse/personal-brand/videos/L05.mp4", "kurse/personal-brand/videos/L05.jpg", "Dein Brand-Paket"]], "text": "Dein Brand-Paket ist ein Ordner, den jede KI versteht. Du legst ihn in ein Projekt – und alles, was entsteht, passt zu dir.", "punkte": ["Ein Ordner: <code>SKILL.md</code>, Beispiele, Fotos, Logo", "In jedes neue Projekt kopieren oder zentral ablegen", "Nach jedem Ergebnis: Regel ergänzen, wenn etwas nicht passt", "Als ZIP kannst du ihn auch in die Claude-App hochladen"], "aufgabe": "Bau deinen Ordner zusammen und lass dir einen ersten Post in deinem Stil erstellen.", "prompt": "Nutze meinen Brand-Skill. Schreib einen Instagram-Post über mein Angebot und gestalte dazu ein Bild in meinem Look. Sag mir danach, welche Regel im Skill noch fehlt.", "links": [["Skill: Personal Brand", "?", "Kostenlos im Flow DNA Store"]]}], "spick": [["Brand DNA", "Wer: [Angebot, Stärke]\nFür wen: [Zielgruppe, Problem]\nWarum: [Werte, Antrieb]"], ["SKILL.md", "name: mein-name-brand\ndescription: Nutzen bei jedem Text.\n\n# Stimme\n- du, kurze Sätze\n- keine Floskeln\n# Look\n- Farben: #… #… Akzent #…"], ["Fotos", "Porträt · Arbeit · Ergebnis\nPersönlich · Querformat"]], "faq": [["Ich weiß nicht, was mich besonders macht.", "Frag drei Kunden oder Freunde, wofür sie dich empfehlen würden. Das Interview mit der KI hilft beim Sortieren."], ["Die Texte klingen noch nicht nach mir.", "Gib mehr echte Beispiele und schreib auf, was dich stört. Jede Korrektur wird eine Regel im Skill."], ["Brauche ich ein Logo?", "Nein. Dein Name in einer klaren Schrift reicht für den Start."], ["Ich hänge fest.", "Frag in der Tech-Support-Gruppe (Tab Community) – dort helfen Maik und die Community."]], "ende": {"titel": "Deine Marke. Dein Skill.", "text": "Du hast jetzt ein Brand-Paket, das jede KI versteht. Nächster Schritt: Mach daraus deine Website – im Kurs „Bau deine Premium-Website mit Skill“."}}, "erste-app": {"status": "live", "code": "FLOW-APP-73", "dauer": "ca. 3 Min. Video · 2 Std. Umsetzen", "hinweis": "Animierte Videos mit KI-Stimme (gekennzeichnet). Jede Lektion endet mit einer Aufgabe.", "intro": {"video": "kurse/erste-app/videos/L00.mp4", "poster": "kurse/erste-app/videos/L00.jpg", "titel": "Von der Idee zur App auf dem Handy"}, "module": ["Die Idee schärfen", "Material sammeln", "5 Versionen bauen lassen", "Die beste wählen", "Aufs Handy und teilen"], "bereiche": {}, "lektionen": [{"videos": [["kurse/erste-app/videos/L01.mp4", "kurse/erste-app/videos/L01.jpg", "Die Idee schärfen"]], "text": "Eine App scheitert selten an der Technik, sondern an einer unklaren Idee. Drei Sätze und eine Hauptfunktion – dann wird sie fertig.", "punkte": ["<b>Problem</b>: was nervt oder fehlt", "<b>Nutzer</b>: wer benutzt die App, wann, wo", "<b>Funktion</b>: die eine Hauptsache", "Alles Weitere kommt auf eine „Später“-Liste"], "aufgabe": "Schreib deine App-Idee in drei Sätzen auf.", "prompt": "Meine App-Idee: [Problem], für [Nutzer], Hauptfunktion: [eine Sache]. Stell mir 5 Fragen, die ich noch nicht bedacht habe. Schlag dann die kleinste Version vor, die schon nützlich ist."}, {"videos": [["kurse/erste-app/videos/L02.mp4", "kurse/erste-app/videos/L02.jpg", "Material sammeln"]], "text": "Die KI baut aus dem, was du ihr gibst. Ein aufgeräumter Ordner mit Anforderungen und Material ist die halbe App.", "punkte": ["<code>Anforderungen.md</code>: deine drei Sätze plus Wünsche", "<code>Content/Media</code>, <code>Texte</code>, <code>Ideen</code>", "Ein Stil-Vorbild nennen – als Vorlage, nicht zum Kopieren", "Keine fremden Bilder oder Texte ohne Erlaubnis"], "aufgabe": "Leg den Ordner an und füll Anforderungen und mindestens einen Unterordner."}, {"videos": [["kurse/erste-app/videos/L03.mp4", "kurse/erste-app/videos/L03.jpg", "5 Versionen bauen lassen"]], "text": "Sich eine App vorher auszudenken ist schwer. Fünf Versionen anzuschauen ist leicht. Darum baut der Skill erst die Auswahl.", "punkte": ["Fünf Dateien, jede per Doppelklick im Browser offen", "Gleiche Inhalte, verschiedener Aufbau und Stil", "Jede Version hat die Hauptfunktion – sonst ist der Vergleich unfair", "Auf dem Handy testen, nicht nur am Computer"], "aufgabe": "Schick den Start-Prompt und klick alle fünf Versionen durch.", "prompt": "Nutze den App-Builder-Skill. Lies Anforderungen und Content und bau mir fünf klickbare Versionen meiner App – jede mit anderem Aufbau und Stil. Zeig mir danach eine Übersicht.", "links": [["App Builder", "?", "Skill im Flow DNA Store – mit 1, 3 oder 5 Versionen"]]}, {"videos": [["kurse/erste-app/videos/L04.mp4", "kurse/erste-app/videos/L04.jpg", "Die beste wählen"]], "text": "Du bist der Regisseur. Aus den besten Teilen der fünf Versionen wird eine neue – und die verbesserst du Satz für Satz.", "punkte": ["Mischen ist ausdrücklich erlaubt", "Feedback konkret: was gefällt, was stört", "Neue Version bauen lassen, alte behalten", "Echten Nutzer testen lassen – nicht nur du"], "aufgabe": "Gib Feedback zu den Versionen und lass dir Version 6 bauen.", "prompt": "Mir gefällt [Teil] von Version [n], [Teil] von Version [n]. Mich stört [Punkt]. Bau daraus Version 6 und lass die alten Versionen unverändert."}, {"videos": [["kurse/erste-app/videos/L05.mp4", "kurse/erste-app/videos/L05.jpg", "Aufs Handy und teilen"]], "text": "Eine Web-App braucht keinen App Store. Sie läuft im Browser, lässt sich auf den Startbildschirm legen und per Link teilen.", "punkte": ["Online stellen z. B. kostenlos mit GitHub Pages", "Android: Menü → „App installieren“", "iPhone: in Safari Teilen → „Zum Home-Bildschirm“", "Keine Zugangsdaten oder privaten Daten in die App schreiben"], "aufgabe": "Stell deine App online und installier sie auf deinem Handy.", "prompt": "Mach die App installierbar (Web-App mit Icon) und stell sie online. Frag mich vorher, ob auf meinem GitHub-Account oder nur lokal. Gib mir am Ende den Link und eine kurze Anleitung zum Installieren für iPhone und Android.", "links": [["GitHub", "https://github.com/signup", "Kostenlosen Account anlegen"]]}], "spick": [["Idee", "Problem: …\nNutzer: …\nHauptfunktion: …"], ["Ordner", "meine-app/\n  Anforderungen.md\n  Content/Media\n  Content/Texte\n  Content/Ideen"], ["Feedback", "Aufbau von 1, Farben von 4.\nMich stört: …\nBau daraus Version 6."]], "faq": [["Muss ich programmieren können?", "Nein. Du beschreibst, die KI baut. Du solltest aber testen und klar sagen können, was du willst."], ["Die Versionen sehen sich zu ähnlich.", "Sag es direkt: „Die Versionen sollen sich im Aufbau unterscheiden, nicht nur in der Farbe.“"], ["Kann die App Daten speichern oder ein Login haben?", "Ja, das geht – ist aber ein zweiter Schritt. Starte ohne und erweitere, wenn die Hauptfunktion sitzt."], ["Kostet das Online-Stellen etwas?", "GitHub Pages ist für öffentliche Projekte kostenlos. Eine eigene Domain kostet extra."], ["Ich hänge fest.", "Frag in der Tech-Support-Gruppe (Tab Community) – dort helfen Maik und die Community."]], "ende": {"titel": "Deine App läuft.", "text": "Du hast aus einer Idee eine App gemacht. Wenn du tiefer einsteigen willst: Im Kurs „Claude Code für Einsteiger“ lernst du das Werkzeug dahinter richtig kennen."}}, "claude-code": {"status": "live", "code": "FLOW-CODE-86", "dauer": "ca. 3 Min. Video · 2–3 Std. Umsetzen", "hinweis": "Animierte Videos mit KI-Stimme (gekennzeichnet). Jede Lektion endet mit einer Aufgabe.", "intro": {"video": "kurse/claude-code/videos/L00.mp4", "poster": "kurse/claude-code/videos/L00.jpg", "titel": "Die KI, die in deinem Ordner arbeitet"}, "module": ["Installation und erste Session", "Projektordner und CLAUDE.md", "Skills: Wissen, das bleibt", "Bauen, testen, verbessern", "GitHub und Veröffentlichen", "Arbeiten mit Agenten"], "bereiche": {}, "lektionen": [{"videos": [["kurse/claude-code/videos/L01.mp4", "kurse/claude-code/videos/L01.jpg", "Installation und erste Session"]], "text": "Claude Code ist kein Programm für Programmierer. Du brauchst die App, ein Konto und einen Ordner – der Rest ist ein Gespräch.", "punkte": ["Claude-App installieren und anmelden (für Claude Code ist ein Abo nötig)", "Einen <b>leeren Ordner</b> für dein erstes Projekt wählen", "In normalen Sätzen schreiben, was entstehen soll", "Änderungen ansehen und freigeben"], "aufgabe": "Installier die App und lass dir deine erste Datei erstellen.", "prompt": "Erstell in diesem Ordner eine Datei hallo.html mit einer schönen Seite, auf der mein Name steht. Öffne sie danach und erklär mir in zwei Sätzen, was du gemacht hast.", "links": [["Claude App", "https://claude.com/download", "Download für Mac und Windows"]]}, {"videos": [["kurse/claude-code/videos/L02.mp4", "kurse/claude-code/videos/L02.jpg", "Projektordner und CLAUDE.md"]], "text": "Die CLAUDE.md ist die wichtigste Datei in deinem Projekt. Mit ihr fängt keine Session bei null an.", "punkte": ["Ein Projekt = ein Ordner", "<code>CLAUDE.md</code> im Hauptordner: Zweck, wer du bist, Regeln, Aufbau", "Wenn Claude etwas falsch macht: „Schreib das als Regel in die CLAUDE.md“", "Keine Passwörter oder Schlüssel hineinschreiben"], "aufgabe": "Lass dir für dein Projekt eine CLAUDE.md anlegen.", "prompt": "Schau dir diesen Ordner an und schreib eine CLAUDE.md. Stell mir vorher 5 Fragen zu mir, meinem Ziel und meinen Regeln. Halte sie kurz und konkret."}, {"videos": [["kurse/claude-code/videos/L03.mp4", "kurse/claude-code/videos/L03.jpg", "Skills: Wissen, das bleibt"]], "text": "Skills machen aus einer guten Session ein wiederholbares Ergebnis. Statt jedes Mal neu zu erklären, lädt Claude die passende Anleitung.", "punkte": ["Skill = Ordner mit <code>SKILL.md</code> (Name, Beschreibung, Anleitung)", "Ablage: <code>.claude/skills/</code> im Projekt", "Claude nutzt ihn automatisch, wenn die Aufgabe passt – oder du sagst „Nutze den Skill …“", "Fertige Skills gibt es im Flow DNA Store"], "aufgabe": "Lade einen Free-Skill aus dem Store und leg ihn in dein Projekt.", "links": [["Skill Store", "?", "Free- und Premium-Skills"]]}, {"videos": [["kurse/claude-code/videos/L04.mp4", "kurse/claude-code/videos/L04.jpg", "Bauen, testen, verbessern"]], "text": "Kein Ergebnis ist beim ersten Mal perfekt – muss es auch nicht. Der Kreislauf aus Bauen, Ansehen und Feedback macht es gut.", "punkte": ["Kleine Schritte: eine Änderung, ansehen, nächste", "Feedback konkret – was genau, wo genau", "Fehlermeldungen vollständig kopieren", "Claude selbst testen lassen, bevor du abnimmst"], "aufgabe": "Verbessere dein Projekt in drei kleinen Runden mit konkretem Feedback.", "prompt": "Öffne die Seite, klick alle Buttons durch und prüf sie auf dem Handy-Format. Sag mir ehrlich, was noch nicht funktioniert, und behebe es."}, {"videos": [["kurse/claude-code/videos/L05.mp4", "kurse/claude-code/videos/L05.jpg", "GitHub und Veröffentlichen"]], "text": "Mit GitHub ist deine Arbeit gesichert und mit GitHub Pages in ein bis zwei Minuten online – ohne dass du einen Befehl tippen musst.", "punkte": ["Kostenlosen GitHub-Account anlegen", "Claude sichert („commit“) und lädt hoch („push“)", "GitHub Pages: Seite ist nach 1–2 Minuten erreichbar", "Öffentliche Repos sind für alle sichtbar – Privates gehört nicht hinein"], "aufgabe": "Sichere dein Projekt auf GitHub und stell es online.", "prompt": "Sichere den aktuellen Stand auf GitHub und stell die Seite mit GitHub Pages online. Frag mich vorher nach meinem Account und prüf, dass keine Passwörter oder privaten Daten im Ordner liegen.", "links": [["GitHub", "https://github.com/signup", "Kostenlosen Account anlegen"]]}, {"videos": [["kurse/claude-code/videos/L06.mp4", "kurse/claude-code/videos/L06.jpg", "Arbeiten mit Agenten"]], "text": "Agenten sind kein Muss für den Anfang. Aber gut zu wissen: Wenn Aufgaben größer werden, kann Claude sie aufteilen und sogar regelmäßig von selbst erledigen.", "punkte": ["Agenten = Helfer, die Teilaufgaben parallel erledigen", "Gut für Recherche, Prüfen, wiederkehrende Aufgaben", "Kosten im Blick behalten: mehr Agenten = mehr Verbrauch", "Automatisieren erst, wenn der Ablauf von Hand funktioniert"], "aufgabe": "Lass ein Ergebnis von einem zweiten Agenten kritisch prüfen.", "prompt": "Recherchiere zu [Thema] mit mehreren Agenten parallel und lass einen weiteren Agenten das Ergebnis kritisch prüfen. Fass am Ende kurz zusammen.", "bonus": true}], "spick": [["Start", "1. Claude-App öffnen\n2. Ordner wählen\n3. In normalen Sätzen\n   schreiben, was entstehen soll"], ["CLAUDE.md", "# Wofür\n# Wer ich bin\n# Regeln\n- nichts erfinden\n# Aufbau\n- ordner/ – wofür"], ["Feedback", "Was genau, wo genau.\nFehlermeldung komplett.\n„Prüf es selbst und\nsag ehrlich, was fehlt.“"]], "faq": [["Brauche ich das Terminal?", "Nein. In der Claude-App arbeitest du in einem normalen Fenster. Das Terminal ist nur eine von mehreren Möglichkeiten."], ["Kann Claude etwas kaputt machen?", "Es fragt vor Änderungen um Erlaubnis. Arbeite in einem eigenen Projektordner und sichere regelmäßig auf GitHub – dann kommst du immer zurück."], ["Claude macht etwas anderes, als ich wollte.", "Stoppen, genauer beschreiben, Beispiel geben. Und die Regel in die CLAUDE.md schreiben lassen."], ["Was kostet das?", "Claude Code ist in den bezahlten Claude-Abos enthalten. Aktuelle Preise stehen bei Anthropic."], ["Ich hänge fest.", "Frag in der Tech-Support-Gruppe (Tab Community) – dort helfen Maik und die Community."]], "ende": {"titel": "Du kannst jetzt bauen.", "text": "Du kennst das Werkzeug: Ordner, CLAUDE.md, Skills, Kreislauf, GitHub. Wenn du das mit persönlicher Begleitung vertiefen willst: Maiks 1:1-Begleitung enthält eine 7-stündige Masterclass rund um Claude Code."}}, "content-system": {"status": "live", "code": "FLOW-CONTENT-29", "dauer": "ca. 3 Min. Video · 90 Min. Umsetzen", "hinweis": "Animierte Videos mit KI-Stimme (gekennzeichnet). Jede Lektion endet mit einer Aufgabe.", "intro": {"video": "kurse/content-system/videos/L00.mp4", "poster": "kurse/content-system/videos/L00.jpg", "titel": "Ein System statt jeden Tag neu überlegen"}, "module": ["Themenpool und Rotation", "Hooks, die stoppen", "Reels schneiden mit KI", "Captions in deinem Ton", "Zahlen lesen und lernen"], "bereiche": {}, "lektionen": [{"videos": [["kurse/content-system/videos/L01.mp4", "kurse/content-system/videos/L01.jpg", "Themenpool und Rotation"]], "text": "Ein Themenpool nimmt dir die tägliche Entscheidung ab. Vier Säulen, je fünf Ideen, ein Verlauf – und die KI schlägt dir das nächste Thema vor.", "punkte": ["Vier Säulen: Zeigen · Erklären · Persönlich · Angebot", "Ideen aus echtem Material – Projekte, Fragen von Kunden, Fehler", "Verlauf führen: Datum, Thema, Format", "Nicht jeden Post zur Verkaufsanzeige machen"], "aufgabe": "Lass dir einen Themenpool mit 20 Ideen erstellen und streich, was nicht zu dir passt.", "prompt": "Hier ist, was ich mache: [kurz beschreiben]. Bau mir einen Themenpool mit vier Säulen (Zeigen, Erklären, Persönlich, Angebot) und je fünf konkreten Post-Ideen aus meinem echten Alltag. Erfinde keine Kunden oder Ergebnisse."}, {"videos": [["kurse/content-system/videos/L02.mp4", "kurse/content-system/videos/L02.jpg", "Hooks, die stoppen"]], "text": "Ein Hook ist kein Trick, sondern ein ehrliches Versprechen in einer Sekunde. Wer konkret wird, gewinnt.", "punkte": ["Erstes Bild: Mensch oder Bewegung, kein Logo", "Hook-Text in einer Sekunde lesbar (max. 7 Wörter)", "Vier Typen: Ergebnis · Zahl · Frage · Überraschung", "Pro Post nur <b>eine</b> Sache testen"], "aufgabe": "Lass dir für dein nächstes Thema fünf Hooks geben und wähl den ehrlichsten.", "prompt": "Mein Reel zeigt: [Inhalt]. Gib mir 5 Hooks – je einen als Ergebnis, echte Zahl, Frage, Überraschung und POV. Maximal 7 Wörter, nichts versprechen, was das Video nicht zeigt."}, {"videos": [["kurse/content-system/videos/L03.mp4", "kurse/content-system/videos/L03.jpg", "Reels schneiden mit KI"]], "text": "Du musst kein Schnittprogramm lernen. Du nimmst auf, die KI schneidet – und du entscheidest, ob es nach dir klingt.", "punkte": ["Eigenes Material zuerst: Selfie, Bildschirmaufnahme, Fotos", "7–15 Sekunden, Erklär-Reels bis etwa 30", "Untertitel und Text im Bild – läuft auch ohne Ton", "Musik nur mit Lizenz, KI-Clips kennzeichnen"], "aufgabe": "Nimm ein 30-Sekunden-Selfie-Video zu einem deiner Themen auf.", "prompt": "Schneide dieses Video zu einem Reel (9:16): Ähms und Pausen raus, stärksten Satz nach vorn, Wort-Untertitel in meinem Look, lizenzfreie Musik leise darunter. Zeig mir vorher die Schnittliste.", "links": [["Video Cutting", "?", "Skill im Flow DNA Store"]]}, {"videos": [["kurse/content-system/videos/L04.mp4", "kurse/content-system/videos/L04.jpg", "Captions in deinem Ton"]], "text": "Die Caption entscheidet, ob aus einem Zuschauer ein Follower wird. Mit deinem Brand-Skill klingt sie nach dir statt nach Werbetext.", "punkte": ["Erste Zeile = zweiter Hook", "Mehrwert vor Verkauf", "Am Ende eine echte Frage – oder ein leiser Aufruf", "Nichts behaupten, was nicht stimmt: keine erfundenen Kunden oder Zahlen"], "aufgabe": "Lass dir zu deinem Video zwei Captions schreiben und kürze die bessere um ein Drittel.", "prompt": "Nutze meinen Brand-Skill. Schreib eine Caption zu diesem Post: [Inhalt]. Erste Zeile als Hook, dann der Nutzen, am Ende eine echte Frage. Keine Floskeln, Emojis sparsam, 3–5 Hashtags. Gib mir zwei Varianten."}, {"videos": [["kurse/content-system/videos/L05.mp4", "kurse/content-system/videos/L05.jpg", "Zahlen lesen und lernen"]], "text": "Zahlen sind kein Urteil über dich, sondern ein Hinweis für den nächsten Post. Wer aufschreibt, was funktioniert, wird jede Woche besser.", "punkte": ["Nach 48 Stunden: Durchsehquote, Sends, Saves", "Pro Post nur <b>eine</b> Variable testen (Hook, Länge, Uhrzeit …)", "Learnings in einem Satz festhalten", "Takt wählen, den du durchhältst"], "aufgabe": "Leg dein Lern-Tagebuch an und trag deinen letzten Post ein.", "prompt": "Hier sind die Zahlen meiner letzten 5 Posts: [einfügen]. Was fällt auf? Was sollte ich wiederholen, was lassen? Schlag mir die nächste Testvariable vor.", "links": [["Post Analyzer", "?", "Kostenloser Skill im Flow DNA Store"]]}], "spick": [["Säulen", "Zeigen · Erklären\nPersönlich · Angebot"], ["Hook-Check", "Mensch/Bewegung im 1. Bild\nText in 1 s lesbar\nmax. 7 Wörter\nehrlich"], ["Nach 48 h", "Durchsehquote\nSends · Saves\n1 Satz: Was lerne ich?"]], "faq": [["Ich habe nichts Spannendes zu zeigen.", "Doch: deine Arbeit. Ein Vorher/Nachher, eine Kundenfrage, ein Fehler, ein Werkzeug. Alltag ist für andere neu."], ["Ich mag mich nicht vor der Kamera.", "Starte mit Bildschirmaufnahmen und deiner Stimme oder mit Fotos. Dein Gesicht hilft, ist aber kein Muss für den Anfang."], ["Wie oft soll ich posten?", "So oft, wie du es mit Qualität durchhältst. Drei gute Posts pro Woche sind ein starker Start."], ["Ich hänge fest.", "Frag in der Tech-Support-Gruppe (Tab Community) – dort helfen Maik und die Community."]], "ende": {"titel": "Dein Content läuft.", "text": "Du hast Themen, Hooks, einen Schnitt-Ablauf, Captions in deinem Ton und ein Lern-Tagebuch. Nächster Schritt: wiederkehrende Teile automatisieren – im Kurs „Automatisierung & Workflows“."}}, "automation": {"status": "live", "code": "FLOW-AUTO-64", "dauer": "ca. 3 Min. Video · 2 Std. Umsetzen", "hinweis": "Animierte Videos mit KI-Stimme (gekennzeichnet). Jede Lektion endet mit einer Aufgabe.", "intro": {"video": "kurse/automation/videos/L00.mp4", "poster": "kurse/automation/videos/L00.jpg", "titel": "Wiederkehrende Arbeit abgeben"}, "module": ["Prozesse finden, die sich lohnen", "Geplante Aufgaben und Routinen", "Daten zwischen Tools bewegen", "Beispiel: KI-News von selbst", "Fehler abfangen und überwachen"], "bereiche": {}, "lektionen": [{"videos": [["kurse/automation/videos/L01.mp4", "kurse/automation/videos/L01.jpg", "Prozesse finden, die sich lohnen"]], "text": "Automatisierung lohnt sich dort, wo sich Arbeit wiederholt und der Ablauf klar ist. Wer die richtigen Aufgaben wählt, spart jede Woche Zeit.", "punkte": ["<b>Oft</b>: mindestens wöchentlich", "<b>Klar</b>: immer dieselben Schritte", "<b>Risikoarm</b>: ein Fehler ist korrigierbar", "Mit der einfachsten Aufgabe starten"], "aufgabe": "Finde eine Aufgabe, die du jede Woche machst, und schreib ihre Schritte auf.", "prompt": "Ich beschreibe dir meine Arbeitswoche: [erzählen]. Finde die 5 Aufgaben, die sich am meisten zum Automatisieren lohnen – mit geschätzter Zeitersparnis und Risiko. Womit sollte ich anfangen?"}, {"videos": [["kurse/automation/videos/L02.mp4", "kurse/automation/videos/L02.jpg", "Geplante Aufgaben und Routinen"]], "text": "Geplante Aufgaben machen aus einem guten Prompt einen Mitarbeiter mit festen Zeiten. Starte so, dass du jedes Ergebnis noch siehst.", "punkte": ["Routine = Auftrag + Zeitplan", "Vier Angaben: wann, was, wohin, was nicht", "Ergebnisse zuerst als Entwurf", "Welche Werkzeuge Routinen können, hängt von deinem Tool ab – Claude Code kann geplante Aufgaben"], "aufgabe": "Formuliere deine erste Routine mit den vier Angaben.", "prompt": "Richte eine Routine ein: jeden [Tag] um [Uhrzeit] [Aufgabe]. Schick mir das Ergebnis als Entwurf. Versende oder veröffentliche nichts ohne meine Freigabe."}, {"videos": [["kurse/automation/videos/L03.mp4", "kurse/automation/videos/L03.jpg", "Daten zwischen Tools bewegen"]], "text": "Sobald die KI an deine Daten kommt, wird sie richtig nützlich – und du trägst Verantwortung. Verbinde bewusst und sparsam.", "punkte": ["Quelle → Verarbeitung → Ziel aufschreiben", "Konnektoren verbinden KI mit Kalender, Mail, Ordnern", "Rechte sparsam: lesen vor schreiben", "Keine Zugangsdaten in Prompts oder Dateien"], "aufgabe": "Zeichne für deine Aufgabe auf: Woher kommen die Daten, wohin gehen sie?", "prompt": "Ich möchte [Quelle] mit [Ziel] verbinden: [was soll passieren]. Welche Verbindung brauche ich, welche Rechte sind nötig – und welche nicht? Schlag die sicherste Variante vor."}, {"videos": [["kurse/automation/videos/L04.mp4", "kurse/automation/videos/L04.jpg", "Beispiel: KI-News von selbst"]], "text": "Automatisierung klingt groß, ist aber oft klein: ein Programm, ein Zeitplan, ein Ergebnis. Die KI-News in dieser App sind genau so entstanden.", "punkte": ["Ein Programm + ein Zeitplan + ein Ergebnis", "Feste Abstände reichen fast immer", "Ausfälle einplanen: letzter Stand bleibt", "Quellen nur so nutzen, wie sie es erlauben (z. B. offene Feeds)"], "aufgabe": "Öffne den Tab KI-News und überleg: Welche Info hättest du gern jeden Morgen fertig?", "prompt": "Bau mir eine kleine Automatisierung: Lies alle [Zeitraum] diese Quellen: [Liste]. Fass das Wichtigste zusammen und speichere es als Datei. Wenn eine Quelle ausfällt, behalte den letzten Stand und sag es mir."}, {"videos": [["kurse/automation/videos/L05.mp4", "kurse/automation/videos/L05.jpg", "Fehler abfangen und überwachen"]], "text": "Eine Automatisierung ist erst fertig, wenn sie sich meldet, sobald etwas nicht stimmt. Damit schläfst du ruhig.", "punkte": ["Fehler sichtbar machen – nie still weiterlaufen lassen", "Protokoll: Datum, was lief, Ergebnis", "Stopp-Regel: bei Zweifel anhalten und fragen", "Regelmäßig selbst reinschauen"], "aufgabe": "Schreib für deine Routine auf: Woran merke ich, dass sie nicht mehr läuft?", "prompt": "Ergänze die Automatisierung: Schreib ein Protokoll mit Datum und Ergebnis, melde mir jeden Fehler sofort und stoppe, wenn Daten fehlen oder seltsam aussehen – statt zu raten."}], "spick": [["Lohnt es sich?", "Oft? Klar? Risikoarm?\n→ 3× Ja = automatisieren"], ["Routine", "Wann: …\nWas: …\nWohin: …\nNicht: ohne OK versenden"], ["Sicherung", "Fehler melden\nProtokoll führen\nBei Zweifel stoppen"]], "faq": [["Brauche ich dafür teure Tools?", "Nein. Vieles geht mit Claude Code, geplanten Aufgaben und kostenlosen Diensten. Starte klein."], ["Was, wenn die KI etwas Falsches verschickt?", "Darum gehen Ergebnisse anfangs nur als Entwurf an dich. Erst wenn es wochenlang passt, lockerst du die Freigabe."], ["Ich bin nicht technisch.", "Du musst den Ablauf beschreiben können – die Technik baut die KI. Schreib die Schritte so auf, wie du sie einer Aushilfe erklären würdest."], ["Ich hänge fest.", "Frag in der Tech-Support-Gruppe (Tab Community) – dort helfen Maik und die Community."]], "ende": {"titel": "Deine Arbeit läuft mit.", "text": "Du weißt, was sich lohnt, wie eine Routine aussieht und wie du sie absicherst. Nächster Schritt: Mach aus deinem besten Ablauf einen Skill – im Kurs „Skills bauen & verkaufen“."}}, "skills": {"status": "live", "code": "FLOW-SKILLS-37", "dauer": "ca. 3 Min. Video · 2 Std. Umsetzen", "hinweis": "Animierte Videos mit KI-Stimme (gekennzeichnet). Jede Lektion endet mit einer Aufgabe.", "intro": {"video": "kurse/skills/videos/L00.mp4", "poster": "kurse/skills/videos/L00.jpg", "titel": "Dein Wissen als Skill"}, "module": ["Was ist ein Skill?", "Deinen ersten Skill schreiben", "Testen und verbessern", "Skill-Paket schnüren", "Im Flow DNA Store anbieten"], "bereiche": {}, "lektionen": [{"videos": [["kurse/skills/videos/L01.mp4", "kurse/skills/videos/L01.jpg", "Was ist ein Skill?"]], "text": "Ein Skill ist verpacktes Können: eine Anleitung, die die KI immer wieder nutzt. Das macht aus einmaligem Glück ein wiederholbares Ergebnis.", "punkte": ["<b>Name &amp; Beschreibung</b>: entscheidet, wann die KI den Skill lädt", "<b>Anleitung</b>: Schritte, Regeln, Qualitäts-Check", "<b>Dateien</b>: Vorlagen, Beispiele, Skripte", "Funktioniert in Claude Code, der Claude-App und Codex"], "aufgabe": "Öffne einen Free-Skill aus dem Store und lies seine SKILL.md.", "links": [["Installation", "skills/INSTALLATION.md", "So legst du einen Skill ab"]]}, {"videos": [["kurse/skills/videos/L02.mp4", "kurse/skills/videos/L02.jpg", "Deinen ersten Skill schreiben"]], "text": "Du schreibst einen Skill nicht aus dem Kopf, sondern aus einer gelungenen Session. Was gerade funktioniert hat, wird zur Anleitung.", "punkte": ["Thema: eine Aufgabe, die du oft erklärst", "<code>description</code> sagt klar, <b>wann</b> der Skill genutzt wird", "Ablauf in nummerierten Schritten", "Regeln und Tabus dazu – z. B. „nichts erfinden“"], "aufgabe": "Erledige eine Aufgabe mit der KI und lass daraus deinen ersten Skill schreiben.", "prompt": "Wir haben gerade zusammen [Aufgabe] erledigt. Mach aus diesem Ablauf einen Skill: SKILL.md mit name, description (wann nutzen), Schritten, Regeln und einem Qualitäts-Check. Leg ihn unter .claude/skills/[name]/ ab."}, {"videos": [["kurse/skills/videos/L03.mp4", "kurse/skills/videos/L03.jpg", "Testen und verbessern"]], "text": "Testen heißt: frischer Chat, echte Aufgabe, kein Nachhelfen. Jede Korrektur, die du machen musst, gehört als Regel in den Skill.", "punkte": ["Neuer Chat ohne Vorwissen", "Drei verschiedene Testaufgaben", "Korrekturen sofort als Regel eintragen", "Version und Datum im Skill notieren"], "aufgabe": "Teste deinen Skill in einem neuen Chat und ergänze mindestens eine Regel.", "prompt": "Teste meinen Skill [Name] mit drei verschiedenen Aufgaben. Sag mir ehrlich, wo die Anleitung unklar ist oder etwas fehlt, und schlag konkrete Ergänzungen vor."}, {"videos": [["kurse/skills/videos/L04.mp4", "kurse/skills/videos/L04.jpg", "Skill-Paket schnüren"]], "text": "Zwischen „funktioniert bei mir“ und „funktioniert bei anderen“ liegt das Paket: Vorlagen, Beispiele, klare Beschreibung – und nichts Privates.", "punkte": ["Ordner: <code>SKILL.md</code>, Vorlagen, Beispiele, README", "Private Daten raus, Platzhalter rein", "Beschreiben: Für wen, was er kann, was nicht", "Fremde Inhalte nur mit Erlaubnis oder freier Lizenz"], "aufgabe": "Mach aus deinem Skill ein Paket mit README und einem Beispiel.", "prompt": "Mach aus meinem Skill [Name] eine Store-Version: Entferne alles Private, ersetze es durch Platzhalter, ergänze README mit Nutzen, Installation und einem Beispiel. Pack alles als ZIP."}, {"videos": [["kurse/skills/videos/L05.mp4", "kurse/skills/videos/L05.jpg", "Im Flow DNA Store anbieten"]], "text": "Ein Skill ist ein digitales Produkt. Wer zeigt, was er damit selbst erreicht, braucht keine großen Werbeversprechen.", "punkte": ["Kostenlos, Kauf oder Miete – du entscheidest", "Einreichen im Store über „Mehr → Verkaufen“", "Der Community Marketplace ist im Aufbau – Einreichungen werden einzeln geprüft", "Nichts versprechen, was der Skill nicht hält"], "aufgabe": "Schreib das Versprechen deines Skills in einem Satz auf.", "links": [["Skill einreichen", "?tab=more", "Im Flow DNA Store unter Mehr → Verkaufen"]]}], "spick": [["SKILL.md", "---\nname: mein-skill\ndescription: Was + wann nutzen.\n---\n# Ablauf\n1. …\n# Regeln\n- …"], ["Test", "Neuer Chat\n3 Aufgaben\nKorrektur → Regel"], ["Paket", "SKILL.md\nvorlagen/\nbeispiele/\nREADME.md"]], "faq": [["Mein Skill wird nicht geladen.", "Prüf Ordner und Dateinamen (<code>SKILL.md</code>) und mach die <code>description</code> konkreter: wofür und wann genau."], ["Wie lang darf ein Skill sein?", "So kurz wie möglich. Starte mit einer Seite; Details kommen in Zusatzdateien."], ["Kann jemand meinen Skill einfach kopieren?", "Eine Datei lässt sich immer kopieren. Im Store gibt es deshalb für Premium-Skills ein Lizenz-System – ein vollständiger Schutz ist das nicht."], ["Was soll er kosten?", "Orientier dich am Nutzen: Wie viel Zeit oder Geld spart er? Schau dir vergleichbare Skills im Store an."], ["Ich hänge fest.", "Frag in der Tech-Support-Gruppe (Tab Community) – dort helfen Maik und die Community."]], "ende": {"titel": "Dein Wissen arbeitet.", "text": "Du hast einen getesteten Skill und ein Paket. Reich ihn im Store ein – oder nutz ihn als Basis für dein Angebot. Wie du daraus ein Geschäft machst, zeigt der Kurs „Die FLOW-Methode“."}}, "flow-methode": {"status": "live", "code": "FLOW-METHODE-52", "dauer": "ca. 3 Min. Video · 2 Std. Umsetzen", "hinweis": "Animierte Videos mit KI-Stimme (gekennzeichnet). Jede Lektion endet mit einer Aufgabe.", "intro": {"video": "kurse/flow-methode/videos/L00.mp4", "poster": "kurse/flow-methode/videos/L00.jpg", "titel": "Von der Idee zum Business in vier Phasen"}, "module": ["F – Fokussieren", "L – Losbauen", "O – Optimieren", "W – Wachsen", "Dein 90-Tage-Plan"], "bereiche": {}, "lektionen": [{"videos": [["kurse/flow-methode/videos/L01.mp4", "kurse/flow-methode/videos/L01.jpg", "F – Fokussieren"]], "text": "Fokussieren heißt entscheiden. Am Ende dieser Phase steht eine Seite: Ziel, Zielgruppe, Angebot, Geschäftsmodell.", "punkte": ["<b>Ziel</b>: was in 90 Tagen stehen soll", "<b>Zielgruppe</b>: konkret, mit ihrem Problem", "<b>Angebot</b>: Ergebnis statt Leistungsliste", "<b>Modell</b>: wofür jemand zahlt"], "aufgabe": "Wähl eine deiner Ideen und erstelle dein einseitiges Konzept.", "prompt": "Ich habe diese Idee: [beschreiben]. Sei mein Sparringspartner: Stell mir nacheinander kritische Fragen zu Ziel, Zielgruppe, Angebot und Geschäftsmodell. Widersprich mir, wo es nötig ist. Fass am Ende alles als einseitiges Konzept zusammen."}, {"videos": [["kurse/flow-methode/videos/L02.mp4", "kurse/flow-methode/videos/L02.jpg", "L – Losbauen"]], "text": "Ein Prototyp beendet das Grübeln. Mit KI steht eine erste Version in Tagen – und erst dann siehst du, was wirklich trägt.", "punkte": ["Kleinste Version, die man zeigen kann", "Mit Skills bauen: Website, App, Landingpage", "Zeitrahmen setzen: Tage, nicht Monate", "Fertig ist besser als perfekt"], "aufgabe": "Entscheide, was dein Prototyp ist, und setz dir ein Datum in den nächsten 14 Tagen.", "prompt": "Hier ist mein Konzept: [einfügen]. Was ist der kleinste Prototyp, mit dem ich das Angebot echten Menschen zeigen kann? Schlag drei Möglichkeiten vor und bau mit mir die einfachste.", "links": [["Kurs 03: Website", "?tab=kurse", "Bau deine Premium-Website mit Skill"], ["Kurs 04: App", "?tab=kurse", "Deine erste App"]]}, {"videos": [["kurse/flow-methode/videos/L03.mp4", "kurse/flow-methode/videos/L03.jpg", "O – Optimieren"]], "text": "Optimieren heißt nicht verschönern, sondern zuhören. Echte Rückmeldungen zeigen, was fehlt – und was du weglassen kannst.", "punkte": ["Fünf echte Testpersonen aus der Zielgruppe", "Beobachten statt erklären", "Drei wichtigste Änderungen umsetzen", "Zahlen messen, z. B. Klicks auf den Haupt-Button"], "aufgabe": "Zeig deinen Prototyp drei Menschen aus deiner Zielgruppe und notier ihre erste Frage.", "prompt": "Hier sind die Rückmeldungen von fünf Testpersonen: [einfügen]. Was sind die drei wichtigsten Änderungen? Was kann weg? Sortier nach Wirkung und Aufwand."}, {"videos": [["kurse/flow-methode/videos/L04.mp4", "kurse/flow-methode/videos/L04.jpg", "W – Wachsen"]], "text": "Wachsen heißt: wiederholbar machen. Was einmal funktioniert hat, wird zum Prozess, zum Paket oder zum Produkt.", "punkte": ["Content-System für Sichtbarkeit", "Wiederkehrende Abläufe automatisieren", "Leistung als Paket mit klarem Ergebnis", "Digitale Produkte: Skills, Kurse, Vorlagen"], "aufgabe": "Schreib auf, welcher Teil deiner Arbeit sich als Paket oder Produkt anbieten ließe.", "prompt": "Mein Angebot funktioniert bei den ersten Kunden: [beschreiben]. Wo kann ich Abläufe automatisieren, was lässt sich als Paket oder digitales Produkt anbieten? Gib mir die drei größten Hebel.", "links": [["Kurs 06: Content", "?tab=kurse", "Content-System mit KI"], ["Kurs 07: Automatisierung", "?tab=kurse", "Automatisierung & Workflows"]]}, {"videos": [["kurse/flow-methode/videos/L05.mp4", "kurse/flow-methode/videos/L05.jpg", "Dein 90-Tage-Plan"]], "text": "Ein Plan macht aus der Methode einen Kalender. Vier Phasen, vier Daten, vier sichtbare Ergebnisse – und ein fester Termin pro Woche mit dir selbst.", "punkte": ["Ein Ziel in einem Satz", "Pro Phase: Datum + sichtbares Ergebnis", "Fester Wochentermin zum Draufschauen", "Mit Sparring geht es leichter – allein oder mit Maik"], "aufgabe": "Erstelle deinen 90-Tage-Plan und trag den ersten Wochentermin in deinen Kalender ein.", "prompt": "Erstell mir einen 90-Tage-Plan nach der FLOW-Methode für dieses Ziel: [Ziel]. Für jede Phase ein Datum, ein sichtbares Ergebnis und die drei wichtigsten Aufgaben. Ich habe pro Woche [Stunden] Zeit.", "links": [["Erstgespräch", "https://calendly.com/flow_media_ai/1-kennenlernen", "Kostenlos und unverbindlich"]]}], "spick": [["FLOW", "F  Fokussieren  Idea2Concept\nL  Losbauen     Concept2Prototype\nO  Optimieren   Prototype2Product\nW  Wachsen      Product2Business"], ["Konzept", "Ziel · Zielgruppe\nAngebot · Modell\n→ eine Seite"], ["90 Tage", "F 2 Wo · L 3 Wo\nO 4 Wo · W 3 Wo"]], "faq": [["Ich habe zu viele Ideen.", "Genau dafür ist Phase F da. Nimm die Idee, für die du schon Material oder erste Interessenten hast."], ["Mein Prototyp ist mir peinlich.", "Das ist normal – und ein gutes Zeichen. Zeig ihn trotzdem. Rückmeldungen sind wertvoller als Politur."], ["Was, wenn niemand zahlen will?", "Dann hast du es früh und günstig gelernt. Zurück zu F: Zielgruppe oder Angebot schärfen."], ["Kann ich die Methode ohne Technikwissen nutzen?", "Ja. Die Kurse 03 und 04 zeigen, wie die KI das Bauen übernimmt."], ["Ich hänge fest.", "Frag in der Tech-Support-Gruppe (Tab Community) – dort helfen Maik und die Community."]], "ende": {"titel": "Du bist im Flow.", "text": "Du kennst die vier Phasen und hast einen Plan. Wenn du jemanden zum Mitdenken und Umsetzen willst: Maik begleitet dich im 1:1-Sparring über 3 oder 6 Monate – starte mit dem kostenlosen Erstgespräch."}}, "kunden-gewinnen": {"status": "live", "code": "FLOW-KUNDEN-95", "dauer": "ca. 3 Min. Video · 2 Std. Umsetzen", "hinweis": "Animierte Videos mit KI-Stimme (gekennzeichnet). Jede Lektion endet mit einer Aufgabe.", "intro": {"video": "kurse/kunden-gewinnen/videos/L00.mp4", "poster": "kurse/kunden-gewinnen/videos/L00.jpg", "titel": "Zeigen statt kalt anrufen"}, "module": ["Zielgruppe und Region wählen", "Websites bewerten", "Vorschau im Branchen-Look", "Rechtssicher Kontakt aufnehmen", "Dein Lead-System im Alltag"], "bereiche": {}, "lektionen": [{"videos": [["kurse/kunden-gewinnen/videos/L01.mp4", "kurse/kunden-gewinnen/videos/L01.jpg", "Zielgruppe und Region wählen"]], "text": "Fokus schlägt Masse. Eine Branche, eine Region, zwanzig Betriebe – damit lernst du mehr als mit tausend Adressen.", "punkte": ["Eine Branche, die du verstehst", "Eine Region, in der du auch vorbeikommen kannst", "20 Betriebe als Startliste", "Nur öffentliche Geschäftsdaten verwenden"], "aufgabe": "Wähl deine Branche und Region und lass dir 20 Betriebe auflisten.", "prompt": "Ich möchte [Branche] in [Ort/Region] ansprechen. Erstell mir aus öffentlichen Quellen eine Liste mit 20 Betrieben: Name, Website, Telefon, Ort. Nur öffentlich angegebene Geschäftsdaten, keine privaten Personen."}, {"videos": [["kurse/kunden-gewinnen/videos/L02.mp4", "kurse/kunden-gewinnen/videos/L02.jpg", "Websites bewerten"]], "text": "Die Bewertung zeigt dir, wo du echten Mehrwert liefern kannst – und gibt dir später konkrete, belegte Punkte für die Nachricht.", "punkte": ["Vier Punkte: Handy · Tempo · Klarheit · Design", "Note 0–10 mit Beleg (Screenshot)", "Sachlich formulieren, nie abwertend", "Nur Betriebe mit echtem Bedarf weiterverfolgen"], "aufgabe": "Lass fünf Websites deiner Liste bewerten und such die zwei mit dem größten Bedarf aus.", "prompt": "Bewerte diese Website: [URL]. Prüfe Handy-Ansicht, Ladezeit, klare Hauptaktion und Design. Vergib eine Note von 0 bis 10, nenne die drei größten Schwächen sachlich und mach Screenshots als Beleg.", "links": [["Lead Agent · Website", "?", "Signature-Skill im Flow DNA Store"]]}, {"videos": [["kurse/kunden-gewinnen/videos/L03.mp4", "kurse/kunden-gewinnen/videos/L03.jpg", "Vorschau im Branchen-Look"]], "text": "Eine Vorschau sagt mehr als jedes Verkaufsgespräch. Der Betrieb sieht sofort, was möglich ist – mit seinen eigenen Inhalten.", "punkte": ["Branchen-Look und Pflicht-Bausteine", "Nur echte Angaben – keine erfundenen Preise oder Bewertungen", "Banner „Konzept-Entwurf“ und für Suchmaschinen gesperrt", "Vorher/Nachher als Bild für die Nachricht"], "aufgabe": "Bau für einen Betrieb deiner Liste eine Vorschau.", "prompt": "Nutze den Website Transformer im Kunden-Modus. Bau aus dieser URL eine Konzeptseite im Branchen-Look: [URL]. Nur echte Angaben des Betriebs, Banner „Konzept-Entwurf – nicht die offizielle Website“, nicht für Suchmaschinen freigeben.", "links": [["Website Transformer", "?", "Skill im Flow DNA Store"]], "beispiele": [["Bäckerei", "demos/baeckerei/", "Demo-Betrieb"], ["Physio", "demos/physio/", "Demo-Betrieb"], ["Friseur", "demos/friseur/", "Demo-Betrieb"]]}, {"videos": [["kurse/kunden-gewinnen/videos/L04.mp4", "kurse/kunden-gewinnen/videos/L04.jpg", "Rechtssicher Kontakt aufnehmen"]], "text": "Guter Kontakt ist persönlich, ehrlich und erlaubt. Dieser Kurs ist keine Rechtsberatung – im Zweifel frag eine Fachperson, bevor du Werbung verschickst.", "punkte": ["Werbe-E-Mails ohne Einwilligung sind in Deutschland in der Regel unzulässig", "Sicherer: Brief, persönlicher Besuch, Empfehlung, Antwort auf Anfragen", "Kurz, persönlich, belegt, ohne Druck", "Keine Rechtsberatung – im Zweifel prüfen lassen"], "aufgabe": "Schreib eine persönliche Nachricht an einen Betrieb und wähl einen erlaubten Weg.", "prompt": "Schreib mir einen kurzen, persönlichen Brief an [Betrieb]: ein Satz zum Betrieb, ein sachlicher Punkt aus der Bewertung, Hinweis auf die Vorschau als Entwurf mit Link, kein Druck. Maximal 120 Wörter, in meinem Ton."}, {"videos": [["kurse/kunden-gewinnen/videos/L05.mp4", "kurse/kunden-gewinnen/videos/L05.jpg", "Dein Lead-System im Alltag"]], "text": "Ein System heißt nicht Masse. Es heißt: jede Woche ein fester, kleiner Ablauf – und eine Liste, die zeigt, wo jeder Kontakt steht.", "punkte": ["Fester Wochenablauf mit kleinen Zahlen", "Liste mit Status führen", "Einmal freundlich nachfassen, dann loslassen", "Den Ablauf später als Skill automatisieren – der Versand bleibt bei dir"], "aufgabe": "Leg deine Lead-Liste an und plane deinen festen Termin für diese Woche.", "prompt": "Hier ist meine Lead-Liste: [einfügen]. Sag mir, bei wem ich diese Woche nachfassen sollte, und schreib je eine kurze, freundliche Nachricht. Bei wem sollte ich es lassen?", "links": [["Lead Agent · Website", "?", "Der komplette Ablauf als Skill"]]}], "spick": [["Bewertung", "Handy · Tempo\nKlarheit · Design\nNote 0–10 + Screenshot"], ["Vorschau", "Branchen-Look\nnur echte Angaben\nBanner: Konzept-Entwurf"], ["Kontakt", "Brief · Besuch · Empfehlung\nMail nur mit Einwilligung\nkurz, persönlich, ohne Druck"]], "faq": [["Darf ich Betrieben einfach eine E-Mail schicken?", "Werbung per E-Mail ohne Einwilligung ist in Deutschland in der Regel unzulässig. Nutze Brief, Besuch oder Empfehlung – und lass dich im Zweifel rechtlich beraten."], ["Darf ich Bilder von der alten Website verwenden?", "Für eine nicht öffentliche Vorschau, die nur der Betrieb sieht, als Entwurf markiert. Veröffentlichen erst nach Auftrag und Zustimmung."], ["Niemand antwortet.", "Prüf deine Auswahl (echter Bedarf?) und die Nachricht (persönlich, kurz?). Oft hilft der persönliche Besuch mehr als jede Nachricht."], ["Ist das nicht aufdringlich?", "Nicht, wenn du echten Wert lieferst, ehrlich bleibst und ein Nein sofort akzeptierst."], ["Ich hänge fest.", "Frag in der Tech-Support-Gruppe (Tab Community) – dort helfen Maik und die Community."]], "ende": {"titel": "Dein System steht.", "text": "Du findest passende Betriebe, zeigst eine Vorschau und nimmst fair Kontakt auf. Den ganzen Ablauf gibt es als Signature-Skill „Lead Agent · Website“ im Flow DNA Store."}}};var K=(window.FLOW_KURSE||{}).kurse||[];K.forEach(function(k){if(A[k.id])Object.assign(k,A[k.id])});if(window.FLOW_KURSE)window.FLOW_KURSE.hinweis="Zehn Kurse, kurz und zum Mitmachen: Jede Lektion hat ein Video, einen Prompt zum Kopieren und eine Aufgabe. Das Intro kannst du bei jedem Kurs kostenlos ansehen."})();
